    markers = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] != 0 and grid[r][c] != color]
    out = [row[:] for row in grid]

    # Each row through the rectangle extends away from an off-rectangle marker;
    # with no aligned marker, extend in both directions.
    for r in range(r0, r1 + 1):
